import{_ as e,o as n,c as r,a3 as s}from"./chunks/framework.BlfGB29P.js";const u=JSON.parse('{"title":"生产就绪与发布验收","description":"组织功能、质量、安全、数据、运行、恢复和支持证据，完成 Agent 系统的生产就绪评审与 Go/No-Go 决策。","frontmatter":{"title":"生产就绪与发布验收","description":"组织功能、质量、安全、数据、运行、恢复和支持证据，完成 Agent 系统的生产就绪评审与 Go/No-Go 决策。","verified_at":"2026-08-01","source":["https://sre.google/sre-book/evolving-sre-engagement-model/","https://sre.google/sre-book/release-engineering/","https://sre.google/sre-book/canarying-releases/","https://www.nist.gov/itl/ai-risk-management-framework"],"article":{"type":"concept","structure":"concept"}},"headers":[],"relativePath":"py-agent/architecture/delivery-evolution/production-readiness-release-acceptance.md","filePath":"py-agent/architecture/delivery-evolution/production-readiness-release-acceptance.md","lastUpdated":1786083160000}'),l={name:"py-agent/architecture/delivery-evolution/production-readiness-release-acceptance.md"};function i(t,a,o,h,p,c){return n(),r("div",null,[...a[0]||(a[0]=[s(`<h1 id="生产就绪与发布验收" tabindex="-1">生产就绪与发布验收 <a class="header-anchor" href="#生产就绪与发布验收" aria-label="Permalink to &quot;生产就绪与发布验收&quot;">​</a></h1><blockquote><p>作者：codex-gpt-sol-5.6</p></blockquote><p>“测试通过”和“镜像已部署”都不足以证明 Agent 生产就绪。生产就绪意味着系统在真实身份、数据、流量和故障条件下能满足用户承诺，并且组织有人能够观察、限制、恢复和纠正它。</p><p>本章组织发布决策所需证据；具体测试、评测、容器、SLO 和回滚机制仍由“质量与生产”模块负责。</p><p>证据分别来自<a href="/py-agent/quality/agent-testing/">Agent 测试</a>、<a href="/py-agent/quality/agent-evaluation/">Agent 评测</a>、<a href="/py-agent/quality/security-governance/">安全与治理</a>以及<a href="/py-agent/quality/deployment-reliability/">部署与可靠性</a>。本章不重讲这些机制，而是判断同一个候选版本是否已经拥有足够、当前且可追踪的上线证据。</p><h2 id="_1-评审边界" tabindex="-1">1. 评审边界 <a class="header-anchor" href="#_1-评审边界" aria-label="Permalink to &quot;1. 评审边界&quot;">​</a></h2><h3 id="_1-1-被验收版本" tabindex="-1">1.1 被验收版本 <a class="header-anchor" href="#_1-1-被验收版本" aria-label="Permalink to &quot;1.1 被验收版本&quot;">​</a></h3><p>使用不可变 Release Manifest 绑定应用镜像、配置、Prompt、模型/Adapter、工具目录、Workflow/State、数据库 Schema、索引和评测数据。不能验收“当前最新版”。</p><h3 id="_1-2-发布范围" tabindex="-1">1.2 发布范围 <a class="header-anchor" href="#_1-2-发布范围" aria-label="Permalink to &quot;1.2 发布范围&quot;">​</a></h3><p>明确环境、地域、租户、用户、任务、自动化等级、流量比例和持续时间。Pilot、Canary 和 GA 是不同验收范围。</p><h3 id="_1-3-评审角色" tabindex="-1">1.3 评审角色 <a class="header-anchor" href="#_1-3-评审角色" aria-label="Permalink to &quot;1.3 评审角色&quot;">​</a></h3><p>产品、业务、工程、质量、安全、数据、隐私、平台、SRE/运维和支持分别审查自己拥有的风险。Go/No-Go 的最终权限在发布前确定。</p><h3 id="_1-4-证据截止时间" tabindex="-1">1.4 证据截止时间 <a class="header-anchor" href="#_1-4-证据截止时间" aria-label="Permalink to &quot;1.4 证据截止时间&quot;">​</a></h3><p>证据必须来自候选版本或可证明等价环境，并规定有效期。三个月前模型评测不能自动证明今天的候选组合。</p><h2 id="_2-证据包" tabindex="-1">2. 证据包 <a class="header-anchor" href="#_2-证据包" aria-label="Permalink to &quot;2. 证据包&quot;">​</a></h2><p>生产就绪评审不应依赖口头汇报。最小证据包包括：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Release Manifest</span></span>
<span class="line"><span>范围与验收矩阵</span></span>
<span class="line"><span>测试与评测报告</span></span>
<span class="line"><span>威胁模型与安全测试</span></span>
<span class="line"><span>数据清单与供应商审批</span></span>
<span class="line"><span>性能/容量/成本报告</span></span>
<span class="line"><span>SLO、仪表盘和告警</span></span>
<span class="line"><span>故障注入与恢复演练</span></span>
<span class="line"><span>迁移、Canary、回滚计划</span></span>
<span class="line"><span>Runbook、排班与支持流程</span></span>
<span class="line"><span>开放风险和签字记录</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><p>每份产物记录版本、时间、环境、负责人和结论。</p><h2 id="_3-功能与质量就绪" tabindex="-1">3. 功能与质量就绪 <a class="header-anchor" href="#_3-功能与质量就绪" aria-label="Permalink to &quot;3. 功能与质量就绪&quot;">​</a></h2><h3 id="_3-1-核心旅程" tabindex="-1">3.1 核心旅程 <a class="header-anchor" href="#_3-1-核心旅程" aria-label="Permalink to &quot;3.1 核心旅程&quot;">​</a></h3><p>从公开入口验证高频、高价值和高风险用户任务，使用业务终态作为动作成功证据。覆盖取消、重复、权限不足、依赖失败和部分成功。</p><h3 id="_3-2-agent-质量" tabindex="-1">3.2 Agent 质量 <a class="header-anchor" href="#_3-2-agent-质量" aria-label="Permalink to &quot;3.2 Agent 质量&quot;">​</a></h3><p>在锁定数据集上报告任务成功、事实、忠实性、工具轨迹、安全、关键 Slice 和误差分类。汇总分不能掩盖硬门禁。</p><h3 id="_3-3-回归" tabindex="-1">3.3 回归 <a class="header-anchor" href="#_3-3-回归" aria-label="Permalink to &quot;3.3 回归&quot;">​</a></h3><p>历史生产缺陷和本次修改影响路径进入回归集。候选与批准基线配对比较，报告实际差异和不确定性。</p><h3 id="_3-4-人工流程" tabindex="-1">3.4 人工流程 <a class="header-anchor" href="#_3-4-人工流程" aria-label="Permalink to &quot;3.4 人工流程&quot;">​</a></h3><p>审批、复核、接管和申诉在真实权限与工作台上验证。不能用开发者直接改数据库模拟人工处理成功。</p><h2 id="_4-安全与治理就绪" tabindex="-1">4. 安全与治理就绪 <a class="header-anchor" href="#_4-安全与治理就绪" aria-label="Permalink to &quot;4. 安全与治理就绪&quot;">​</a></h2><h3 id="_4-1-威胁模型" tabindex="-1">4.1 威胁模型 <a class="header-anchor" href="#_4-1-威胁模型" aria-label="Permalink to &quot;4.1 威胁模型&quot;">​</a></h3><p>资产、参与者、数据流、信任边界和高风险滥用案例已更新到候选范围。新增工具、数据源或模型会改变威胁模型。</p><h3 id="_4-2-身份与权限" tabindex="-1">4.2 身份与权限 <a class="header-anchor" href="#_4-2-身份与权限" aria-label="Permalink to &quot;4.2 身份与权限&quot;">​</a></h3><p>验证租户隔离、工具最小权限、参数确认、服务身份、Secret 和管理面。用无权限与跨租户身份执行负面测试。</p><h3 id="_4-3-prompt-injection-与输出" tabindex="-1">4.3 Prompt Injection 与输出 <a class="header-anchor" href="#_4-3-prompt-injection-与输出" aria-label="Permalink to &quot;4.3 Prompt Injection 与输出&quot;">​</a></h3><p>直接/间接注入、记忆污染、工具结果注入和下游 Sink 经过对抗测试。即使模型被操纵，确定性权限和数据边界仍须成立。</p><h3 id="_4-4-供应链" tabindex="-1">4.4 供应链 <a class="header-anchor" href="#_4-4-供应链" aria-label="Permalink to &quot;4.4 供应链&quot;">​</a></h3><p>镜像、依赖、模型权重、Adapter、数据集和运行代码有来源、哈希、扫描、许可和审批。高风险发现有处置或有权责任人接受。</p><h2 id="_5-数据与隐私就绪" tabindex="-1">5. 数据与隐私就绪 <a class="header-anchor" href="#_5-数据与隐私就绪" aria-label="Permalink to &quot;5. 数据与隐私就绪&quot;">​</a></h2><h3 id="_5-1-数据清单" tabindex="-1">5.1 数据清单 <a class="header-anchor" href="#_5-1-数据清单" aria-label="Permalink to &quot;5.1 数据清单&quot;">​</a></h3><p>原始输入、业务记录、Checkpoint、记忆、Embedding、缓存、Trace 和评测副本都有目的、分类、所有者和位置。</p><h3 id="_5-2-供应商与地域" tabindex="-1">5.2 供应商与地域 <a class="header-anchor" href="#_5-2-供应商与地域" aria-label="Permalink to &quot;5.2 供应商与地域&quot;">​</a></h3><p>模型、日志、标注和工具供应商的保留、训练使用、地域和子处理者符合实际账户配置与合同。</p><h3 id="_5-3-保留与删除" tabindex="-1">5.3 保留与删除 <a class="header-anchor" href="#_5-3-保留与删除" aria-label="Permalink to &quot;5.3 保留与删除&quot;">​</a></h3><p>在预发布环境执行一次端到端删除：权威源删除后，记忆、索引、缓存和可定位遥测不再被新请求返回。备份例外有记录。</p><h3 id="_5-4-数据质量" tabindex="-1">5.4 数据质量 <a class="header-anchor" href="#_5-4-数据质量" aria-label="Permalink to &quot;5.4 数据质量&quot;">​</a></h3><p>知识库水位、文档权限、索引完整性、Schema 和业务数据新鲜度有可测门禁。数据漂移有监控和 Owner。</p><h2 id="_6-性能、容量与成本就绪" tabindex="-1">6. 性能、容量与成本就绪 <a class="header-anchor" href="#_6-性能、容量与成本就绪" aria-label="Permalink to &quot;6. 性能、容量与成本就绪&quot;">​</a></h2><h3 id="_6-1-工作负载" tabindex="-1">6.1 工作负载 <a class="header-anchor" href="#_6-1-工作负载" aria-label="Permalink to &quot;6.1 工作负载&quot;">​</a></h3><p>压测匹配真实任务、输入/输出 Token、工具路径、流式、并发和到达模式。仅短 Prompt 的峰值 QPS 不足以验收。</p><h3 id="_6-2-slo" tabindex="-1">6.2 SLO <a class="header-anchor" href="#_6-2-slo" aria-label="Permalink to &quot;6.2 SLO&quot;">​</a></h3><p>交互首反馈、完整结果、后台 Deadline、可用性和质量 SLI 均有定义。仪表盘能从用户结果下钻到模型、工具、队列和资源。</p><h3 id="_6-3-容量" tabindex="-1">6.3 容量 <a class="header-anchor" href="#_6-3-容量" aria-label="Permalink to &quot;6.3 容量&quot;">​</a></h3><p>目标峰值、突发、一个故障域失效和下游配额下仍能满足降级 SLO。扩缩考虑模型冷启动和人工处理能力。</p><h3 id="_6-4-成本" tabindex="-1">6.4 成本 <a class="header-anchor" href="#_6-4-成本" aria-label="Permalink to &quot;6.4 成本&quot;">​</a></h3><p>报告每成功任务成本、长尾、失败重试、人工与观测成本；设置请求、租户和组织预算与异常支出告警。</p><h2 id="_7-可靠性与恢复就绪" tabindex="-1">7. 可靠性与恢复就绪 <a class="header-anchor" href="#_7-可靠性与恢复就绪" aria-label="Permalink to &quot;7. 可靠性与恢复就绪&quot;">​</a></h2><h3 id="_7-1-deadline-与过载" tabindex="-1">7.1 Deadline 与过载 <a class="header-anchor" href="#_7-1-deadline-与过载" aria-label="Permalink to &quot;7.1 Deadline 与过载&quot;">​</a></h3><p>总 Deadline、取消、有限重试、熔断、隔舱、有界队列和优先级通过故障实验。各层不能同时无限重试。</p><h3 id="_7-2-副作用" tabindex="-1">7.2 副作用 <a class="header-anchor" href="#_7-2-副作用" aria-label="Permalink to &quot;7.2 副作用&quot;">​</a></h3><p>工具超时发生在“服务端成功、响应丢失”时，系统能通过操作 ID 查询、幂等或补偿恢复，不直接重复执行。</p><h3 id="_7-3-checkpoint" tabindex="-1">7.3 Checkpoint <a class="header-anchor" href="#_7-3-checkpoint" aria-label="Permalink to &quot;7.3 Checkpoint&quot;">​</a></h3><p>进程、Worker 和节点故障后可恢复，旧 Thread 的 State/Workflow 版本有兼容或固定执行器。恢复不会重复已发生外部动作。</p><h3 id="_7-4-数据恢复" tabindex="-1">7.4 数据恢复 <a class="header-anchor" href="#_7-4-数据恢复" aria-label="Permalink to &quot;7.4 数据恢复&quot;">​</a></h3><p>备份实际还原，测量业务数据、配置、模型制品、索引和审计的 RTO/RPO。备份作业成功不是恢复证据。</p><h3 id="_7-5-降级" tabindex="-1">7.5 降级 <a class="header-anchor" href="#_7-5-降级" aria-label="Permalink to &quot;7.5 降级&quot;">​</a></h3><p>备用模型、只读、缓存、后台或安全失败阶梯已经离线评测和演练，仍满足数据政策与最低质量。</p><h2 id="_8-可观测与运营就绪" tabindex="-1">8. 可观测与运营就绪 <a class="header-anchor" href="#_8-可观测与运营就绪" aria-label="Permalink to &quot;8. 可观测与运营就绪&quot;">​</a></h2><h3 id="_8-1-lineage" tabindex="-1">8.1 Lineage <a class="header-anchor" href="#_8-1-lineage" aria-label="Permalink to &quot;8.1 Lineage&quot;">​</a></h3><p>一个用户任务可关联 Task、Run、Trace、Prompt、模型、工具、索引、配置和评测。内容采集遵守隐私最小化。</p><h3 id="_8-2-告警" tabindex="-1">8.2 告警 <a class="header-anchor" href="#_8-2-告警" aria-label="Permalink to &quot;8.2 告警&quot;">​</a></h3><p>面向用户影响、SLO 燃烧、高风险工具、队列 Deadline、数据新鲜度和预算设置可行动告警；每个告警有 Owner 与 Runbook。</p><h3 id="_8-3-runbook" tabindex="-1">8.3 Runbook <a class="header-anchor" href="#_8-3-runbook" aria-label="Permalink to &quot;8.3 Runbook&quot;">​</a></h3><p>覆盖模型不可用、质量退化、工具故障、积压、跨租户事件、Secret 泄露、索引回退、任务重放和人工接管。</p><h3 id="_8-4-运营工具" tabindex="-1">8.4 运营工具 <a class="header-anchor" href="#_8-4-运营工具" aria-label="Permalink to &quot;8.4 运营工具&quot;">​</a></h3><p>支持人员能按权限查看任务、证据和错误，取消/重试/转人工；管理操作有审计且不能直接绕过业务状态机。</p><h2 id="_9-组织就绪" tabindex="-1">9. 组织就绪 <a class="header-anchor" href="#_9-组织就绪" aria-label="Permalink to &quot;9. 组织就绪&quot;">​</a></h2><h3 id="_9-1-所有权" tabindex="-1">9.1 所有权 <a class="header-anchor" href="#_9-1-所有权" aria-label="Permalink to &quot;9.1 所有权&quot;">​</a></h3><p>应用、模型路由、Prompt、工具、数据、索引、评测、安全、平台和业务结果都有明确 Owner。供应商故障不等于没有内部责任人。</p><h3 id="_9-2-值班与支持" tabindex="-1">9.2 值班与支持 <a class="header-anchor" href="#_9-2-值班与支持" aria-label="Permalink to &quot;9.2 值班与支持&quot;">​</a></h3><p>服务时间、On-call、升级路径、人工队列、用户沟通和事件分级已经演练。7×24 承诺需要对应人员和权限。</p><h3 id="_9-3-培训" tabindex="-1">9.3 培训 <a class="header-anchor" href="#_9-3-培训" aria-label="Permalink to &quot;9.3 培训&quot;">​</a></h3><p>用户和支持人员理解能力边界、确认、引用、不确定性、隐私和反馈。培训不能被隐藏的系统提示词替代。</p><h3 id="_9-4-责任边界" tabindex="-1">9.4 责任边界 <a class="header-anchor" href="#_9-4-责任边界" aria-label="Permalink to &quot;9.4 责任边界&quot;">​</a></h3><p>高影响决定的最终责任、人工审核和申诉流程明确，不能把责任归给模型或泛化“业务方”。</p><h2 id="_10-发布计划" tabindex="-1">10. 发布计划 <a class="header-anchor" href="#_10-发布计划" aria-label="Permalink to &quot;10. 发布计划&quot;">​</a></h2><h3 id="_10-1-前置条件" tabindex="-1">10.1 前置条件 <a class="header-anchor" href="#_10-1-前置条件" aria-label="Permalink to &quot;10.1 前置条件&quot;">​</a></h3><p>制品、配置、迁移、配额、Feature Flag、仪表盘、告警、回滚和沟通均准备完成；发布窗口和变更冻结范围明确。</p><h3 id="_10-2-渐进流量" tabindex="-1">10.2 渐进流量 <a class="header-anchor" href="#_10-2-渐进流量" aria-label="Permalink to &quot;10.2 渐进流量&quot;">​</a></h3><p>按内部用户、租户或会话稳定分组逐级扩大。多轮 Session 保持版本粘性；Shadow 候选不得产生真实写副作用。</p><h3 id="_10-3-自动停止" tabindex="-1">10.3 自动停止 <a class="header-anchor" href="#_10-3-自动停止" aria-label="Permalink to &quot;10.3 自动停止&quot;">​</a></h3><p>在发布前定义安全事件、任务成功、p95、错误、成本和积压阈值。严重安全失败可立即停止；统计指标需最低样本与观察窗口。</p><h3 id="_10-4-回滚" tabindex="-1">10.4 回滚 <a class="header-anchor" href="#_10-4-回滚" aria-label="Permalink to &quot;10.4 回滚&quot;">​</a></h3><p>回滚覆盖应用、配置、Prompt、模型、工具、Workflow 和索引；数据与已发生副作用采用兼容、前滚或补偿，不能假设换回镜像即可恢复。</p><h2 id="_11-go-no-go-决策" tabindex="-1">11. Go/No-Go 决策 <a class="header-anchor" href="#_11-go-no-go-决策" aria-label="Permalink to &quot;11. Go/No-Go 决策&quot;">​</a></h2><h3 id="_11-1-gate-状态" tabindex="-1">11.1 Gate 状态 <a class="header-anchor" href="#_11-1-gate-状态" aria-label="Permalink to &quot;11.1 Gate 状态&quot;">​</a></h3><ul><li>Pass：证据达到标准；</li><li>Conditional Pass：低风险、有限期例外，带缓解和 Owner；</li><li>Fail：未达硬门禁；</li><li>Not Evaluated：没有有效证据，不等于 Pass。</li></ul><h3 id="_11-2-例外" tabindex="-1">11.2 例外 <a class="header-anchor" href="#_11-2-例外" aria-label="Permalink to &quot;11.2 例外&quot;">​</a></h3><p>例外记录影响、范围、负责人、到期日、监控、回退和有权批准人。跨租户、未授权写操作、重大隐私和无法恢复等通常不接受上线例外。</p><h3 id="_11-3-决策记录" tabindex="-1">11.3 决策记录 <a class="header-anchor" href="#_11-3-决策记录" aria-label="Permalink to &quot;11.3 决策记录&quot;">​</a></h3><p>Go/No-Go 记录候选 Manifest、证据链接、开放风险、投放范围、停止阈值、签字和下次复查时间。</p><h2 id="_12-填写后的发布摘要" tabindex="-1">12. 填写后的发布摘要 <a class="header-anchor" href="#_12-填写后的发布摘要" aria-label="Permalink to &quot;12. 填写后的发布摘要&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>候选：support-agent-2026.08.01.2</span></span>
<span class="line"><span>范围：30 名售后专员，10% 境内工单，建议 + 确认后退款</span></span>
<span class="line"><span>功能：18/18 关键旅程通过</span></span>
<span class="line"><span>质量：成功率 96.1%；关键事实 99.3%；安全失败 0/420</span></span>
<span class="line"><span>性能：峰值 2x 下首反馈 p95 1.7s，完整结果 p95 16.4s</span></span>
<span class="line"><span>可靠性：模型 429、Worker 终止、重复消息和恢复演练通过</span></span>
<span class="line"><span>数据：境内供应商；删除演练通过；索引水位 2026-07-31</span></span>
<span class="line"><span>运营：告警、Runbook、工作日值班和人工队列已演练</span></span>
<span class="line"><span>开放项：低风险长文本 Slice 延迟偏高；两周内优化，已设 30s 降级</span></span>
<span class="line"><span>决策：Conditional Go；先 5%，24 小时无门禁失败后扩至 10%</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br></div></div><p>示例只展示证据格式，不能作为其他项目阈值。</p><h2 id="_13-发布后验收" tabindex="-1">13. 发布后验收 <a class="header-anchor" href="#_13-发布后验收" aria-label="Permalink to &quot;13. 发布后验收&quot;">​</a></h2><p>发布完成不等于验收结束。观察真实任务、关键 Slice、人工接管、拒绝、回滚、质量代理、成本和数据分布，并与离线基线比较。</p><p>在预定窗口完成 Post-Launch Review：确认是否扩大流量、保持、回退或重新进入 Pilot。新失败样本脱敏标注后加入回归集。</p><h2 id="_14-常见误区" tabindex="-1">14. 常见误区 <a class="header-anchor" href="#_14-常见误区" aria-label="Permalink to &quot;14. 常见误区&quot;">​</a></h2><ol><li><strong>所有测试绿就能上线</strong>：数据、运营、恢复和责任仍可能缺失。</li><li><strong>开发环境演示代替生产证据</strong>：身份、流量和依赖不同。</li><li><strong>发布只看错误率</strong>：质量和成本退化可能不报异常。</li><li><strong>有 Runbook 但未演练</strong>：人员、权限和步骤可能不可用。</li><li><strong>未评测项默认通过</strong>：缺少证据本身就是风险。</li></ol><h2 id="_15-发布验收清单" tabindex="-1">15. 发布验收清单 <a class="header-anchor" href="#_15-发布验收清单" aria-label="Permalink to &quot;15. 发布验收清单&quot;">​</a></h2><ul><li>候选的全部行为和数据版本是否被 Manifest 固定；</li><li>功能、质量、安全、数据、性能、成本、恢复和运营是否都有当前证据；</li><li>关键硬门禁和 Slice 是否单独判定；</li><li>人工审批、支持和值班能力是否在真实权限下演练；</li><li>Canary、自动停止和完整组合回滚是否就绪；</li><li>例外是否低风险、有期限、有缓解并由有权人批准；</li><li>发布后验收是否有观察窗口和扩大/回退标准。</li></ul><p>生产就绪不是一个环境名称，而是一组证据支持的组织能力：系统能完成承诺，失败影响受控，数据和权限可治理，人员能够在真实事故中发现并恢复。</p>`,110)])])}const b=e(l,[["render",i]]);export{u as __pageData,b as default};
